import{z as A,x as s,o as E,c as d,q as l,j as o,D as e,d as t,s as r,S as B,b as n}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"报价与撤单博弈","description":"","frontmatter":{"title":"报价与撤单博弈","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/quote-cancellation-game.md","filePath":"quant/quote-cancellation-game.md","lastUpdated":1791063341000}'),u={name:"quant/quote-cancellation-game.md"};function p(c,a,m,h,F,f){const i=s("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="报价与撤单博弈" tabindex="-1">报价与撤单博弈 <a class="header-anchor" href="#报价与撤单博弈" aria-label="Permalink to &quot;报价与撤单博弈&quot;">​</a></h1><div class="epigraph"><p>电子簿上大多数限价单不会活到成交。撤单与改价是策略，不是系统故障：它缩短被捡窗口，也制造别人必须应对的闪烁深度。</p><footer>—— Hasbrouck and Saar, Technology and liquidity provision: The blurring of traditional definitions, Journal of Financial Markets, 2013</footer></div><p><a href="/quant/hidden-liquidity-theory">隐藏流动性</a>改变事前可见量。缺口是时间维：可见的报价可以在成交前被撤走。Hasbrouck 与 Saar 记录低延迟环境下订单寿命变短、传统「挂单=提供流动性」被模糊。Foucault、Kozhan 与 Tham（2017）把有毒套利与过时报价的撤单竞赛写进理论。本课写撤单作为均衡策略，不为后文报价填塞预支操纵定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Foucault 的限价是一份直到下一期才被捡的期权。若允许连续撤单，期权寿命变成选择变量：寿命短，被捡降、非执行升，且必须付消息与排队重置成本（FIFO 下改价常等于撤旧加新）。问题是最优寿命与最优报价如何联立，以及当许多人高频撤单时，可见深度还有没有 Grossman–Miller 意义上的「在场」。</p><p>另一面：你的撤单是别人的状态冲击。虚假的厚深度诱使市价进入，随即撤走，对方打穿。这在后文幌骚课会升级为操纵意图；本课先承认即使没有操纵意图，理性被捡规避也会产生极高撤单率。</p><h3 id="快相对慢挂单者" tabindex="-1">快相对慢挂单者 <a class="header-anchor" href="#快相对慢挂单者" aria-label="Permalink to &quot;快相对慢挂单者&quot;">​</a></h3><p>van Kervel（2015）等强调多市场：快的人在一处成交后立刻撤其他场所的报价，慢的挂单被留下当被捡对象。撤单博弈因此是速度博弈。Budish 的狙击是同一结构的吃单侧；本课是挂单侧的对称动作——谁先撤过时报价。</p><p><span class="marginnote">统计上撤单率高不等于市场「假」。许多撤单是做市商把库存偏度或信念更新写进报价。要用随后是否重新挂在附近，区分更新与一去不返的撤退。</span></p><p><span class="marginnote">「被捡」（pick-off）就是你的挂单在消息落地后还没来得及撤，被更快的对手按过时价格成交——例如指数公告利空后，你挂在旧价的买单瞬间被人吃走。撤单博弈的核心动作，就是把这个「被捡窗口」压到最短。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把限价寿命 \\(\\tau\\) 放进上一课的效用：\\(\\pi(\\tau)\\)、被捡 \\(E[V\\mid\\mathrm{fill},\\tau]\\) 都随 \\(\\tau\\) 变。消息强度高时最优 \\(\\tau\\) 缩短。技术降低改价成本，均衡寿命下降，成交/消息比下降。Hasbrouck–Saar 称之为流动性供给定义的模糊：大量订单从不意图等到自然成交。</p><p>均衡反馈：若所有做市商 \\(\\tau\\) 极短，市价单面对的有效深度下降，有效价差上升，又会吸引更短 \\(\\tau\\) 的人用速度赚钱。这是军备竞赛的挂单版，频繁批量拍卖课将从设计上切断。</p><h3 id="与库存偏度的关系" tabindex="-1">与库存偏度的关系 <a class="header-anchor" href="#与库存偏度的关系" aria-label="Permalink to &quot;与库存偏度的关系&quot;">​</a></h3><p>Ho–Stoll 的偏度可以通过撤一侧、加另一侧实现。高频下这表现为一侧闪烁。信息更新同样表现为双侧同时撤再重挂更宽。经验分离：库存型撤单不对称且随后中点随库存回复；信息型撤单对称加宽且中点永久移动。</p>',15)),(E(),o(B,null,{default:e(()=>[r(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20News%5B%22%E5%85%AC%E5%85%B1%E4%BF%A1%E6%81%AF%20%2F%20%E4%BB%96%E5%A4%84%E6%88%90%E4%BA%A4%22%5D%20--%3E%20Race%5B%22%E6%92%A4%E8%BF%87%E6%97%B6%E6%8A%A5%E4%BB%B7%20vs%20%E8%A2%AB%E5%90%83%22%5D%0A%20%20Tau%5B%22%E9%80%89%E6%8B%A9%E5%AF%BF%E5%91%BD%20%CF%84%22%5D%20--%3E%20Race%0A%20%20Race%20--%3E%20Eff%5B%22%E6%9C%89%E6%95%88%E6%B7%B1%E5%BA%A6%E4%B8%8E%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Eff%20--%3E%20Tau%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"撤单把「在场」从存量改成流量。Grossman–Miller 的 \\(M\\) 个做市商在场，变成 \\(M\\) 个愿意在未来 \\(\\tau\\) 毫秒内在场的过程。冲击 \\(z\\) 来时，若 \\(\\tau\\) 短于冲击被识别的时间，暂时折让可以变得极大——供给在需要它时消失。这是后文做市义务与闪电崩盘的理论接口。",-1)),(E(),o(B,null,{default:e(()=>[r(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20WD%5B%22%E9%AB%98%E6%92%A4%E5%8D%95%E7%8E%87%E7%9A%84%E4%B8%A4%E7%A7%8D%E5%90%88%E6%B3%95%E6%9D%A5%E6%BA%90%22%5D%20--%3E%20INV%5B%22%E5%BA%93%E5%AD%98%E5%9E%8B%EF%BC%9A%E5%81%8F%E5%BA%A6%E8%B0%83%E6%95%B4%22%5D%0A%20%20WD%20--%3E%20INF%5B%22%E4%BF%A1%E6%81%AF%E5%9E%8B%EF%BC%9A%E4%BF%A1%E5%BF%B5%E6%9B%B4%E6%96%B0%22%5D%0A%20%20INV%20--%3E%20F1%5B%22%E4%B8%8D%E5%AF%B9%E7%A7%B0%EF%BC%9A%E6%92%A4%E4%B8%80%E4%BE%A7%E3%80%81%E5%8A%A0%E5%8F%A6%E4%B8%80%E4%BE%A7%22%5D%0A%20%20INV%20--%3E%20F2%5B%22%E9%9A%8F%E5%90%8E%E4%B8%AD%E7%82%B9%E9%9A%8F%E5%BA%93%E5%AD%98%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20INF%20--%3E%20F3%5B%22%E5%AF%B9%E7%A7%B0%E5%8F%8C%E4%BE%A7%E5%90%8C%E6%97%B6%E5%8A%A0%E5%AE%BD%22%5D%0A%20%20INF%20--%3E%20F4%5B%22%E4%B8%AD%E7%82%B9%E6%B0%B8%E4%B9%85%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20FAST%5B%22%E5%BF%AB%E8%80%85%E5%9C%A8%E6%9F%90%E5%A4%84%E6%88%90%E4%BA%A4%22%5D%20--%3E%20CW%5B%22%E7%AB%8B%E5%88%BB%E6%92%A4%E5%85%B6%E4%BB%96%E5%9C%BA%E6%89%80%E7%9A%84%E8%BF%87%E6%97%B6%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20CW%20--%3E%20SLOW%5B%22%E6%85%A2%E6%8C%82%E5%8D%95%E8%80%85%E8%A2%AB%E7%95%99%E4%B8%8B%E5%BD%93%E8%A2%AB%E6%8D%A1%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">经验上区分这两类撤单有实操价值：库存型撤单不对称、且中点随后往回走，可以当作报价宽度的暂时性处理；信息型撤单对称加宽、中点不回头，此时继续按旧宽度接单就是在接别人不要的尾部。</span></p><p>对 Hasbrouck VAR：报价新息大量来自无成交的改价，信息含量不全在 \\(q\\) 里。只把成交当信息会低估发现速度。报价过程必须进系统，这正是 1991 年文章把报价与成交放在一起的先见。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>把所有短寿命单叫做操纵，在法律与经济上都过宽。操纵需要误导意图与虚假供给，见幌骚课。交易所的最小寿命、撤单费率、订单消息比限制，是直接对 \\(\\tau\\) 征税，会改变均衡，也有把做市赶出明簿的风险。数据档位若只有快照，会完全看不见撤单博弈。</p><p><span class="marginnote">直觉类比：把限价单想成街边摊位，撤单速度就是收摊的快慢。消息一来（隔壁着火），收摊快的人不接烫手生意，收摊慢的摊主只能按旧价成交。技术越先进、改价成本越低，街上摊位的「平均寿命」就越短——这不是故障，是均衡。</span></p><p><span class="marginnote">回测若假设「当时挂着就能吃到」，在高撤单市场是最常见的幻觉。可成交性必须用事件流与撮合规则重建，不能用 Level-1 快照。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>撤单缩短被捡窗口，也缩短有效在场时间；高撤单率可以是理性做市，不必先贴操纵标签。</li><li>寿命 \\(\\tau\\) 与报价联立，技术降低改价成本会推高消息/成交比。</li><li>快者撤跨市场过时报价，慢挂单者承担被捡。</li><li>出处：Hasbrouck and Saar, <em>Journal of Financial Markets</em>, 2013；Foucault, Kozhan and Tham, <em>Review of Financial Studies</em>, 2017；van Kervel, <em>Review of Financial Studies</em>, 2015。</li></ul>',8))])}const _=A(u,[["render",p]]);export{q as __pageData,_ as default};
